/**
 * Self-contained stdio MCP server for Bankstatemently (#6105). No shebang
 * line — this repo bans hashbangs on tracked `.ts` sources
 * (`hashbangRatchet.test.ts`, #5967); every documented invocation is
 * explicit (`node dist/stdio.js`), never a direct `./dist/stdio.js` exec
 * that would need one.
 *
 * Reads `tool-definitions.json` (generated by
 * `packages/backend/src/routes/mcp/generateStdioToolDefinitions.ts` from the
 * hosted registry's real `tools/list` wire output — never hand-authored) and
 * registers every tool with ONE shared handler that calls the public API's
 * `POST /v1/tools/:name` (the SAME generic dispatch `/mcp` and this package
 * both ultimately reach through `createConfiguredMcpServer`,
 * `packages/backend/src/routes/mcp/mcpServerFactory.ts`). No per-tool branch
 * exists here — a new hosted tool needs no code change in this package, only
 * a regenerated `tool-definitions.json`.
 *
 * Self-contained: this file imports nothing from the monorepo
 * (`src/__tests__/selfContained.test.ts` asserts it) — `@modelcontextprotocol/server`
 * is its only runtime dependency.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { McpServer, fromJsonSchema } from '@modelcontextprotocol/server';
import { serveStdio } from '@modelcontextprotocol/server/stdio';
const __dirname = path.dirname(fileURLToPath(import.meta.url));
// One level up from either `src/` (tests, running against source) or
// `dist/` (the built package) — `tool-definitions.json` sits at the package
// root in both cases (`package.json`'s `files` ships it alongside `dist/`).
const TOOL_DEFINITIONS_PATH = path.join(__dirname, '../tool-definitions.json');
/** Local, self-contained record guard — no monorepo shared-package import
 *  reaches this file (self-containment, #6105 AC2). */
function isRecord(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
}
/**
 * A real runtime narrowing guard for the SDK's `CallToolResult` wire shape —
 * a record whose `content` is an array, with `isError` boolean or absent.
 * Deliberately looser than the SDK's own full schema validator: this
 * package runs independently and may talk to a newer/older backend, so it
 * only checks the fields this file actually reads, never over-rejecting on
 * a content-block shape it doesn't otherwise care about.
 */
export function isCallToolResult(value) {
    if (!isRecord(value))
        return false;
    if (!Array.isArray(value.content))
        return false;
    if ('isError' in value && typeof value.isError !== 'boolean')
        return false;
    return true;
}
/** Same shape discipline as `isCallToolResult` — the fields this file
 *  actually reads off a parsed `tool-definitions.json`. */
function isStdioToolDefinitionsFile(value) {
    return isRecord(value)
        && typeof value.version === 'string'
        && typeof value.instructions === 'string'
        && isRecord(value.authErrorResult)
        && Array.isArray(value.tools);
}
/**
 * `tool-definitions.json` is a generator-produced artifact of THIS package
 * (never external/user input crossing a network boundary) but IS a file on
 * disk that can be corrupted, partially written, or stale — `isStdioToolDefinitionsFile`
 * fails loudly at startup rather than serving a broken registry silently.
 */
export function readToolDefinitions(definitionsPath = TOOL_DEFINITIONS_PATH) {
    const parsed = JSON.parse(fs.readFileSync(definitionsPath, 'utf-8'));
    if (!isStdioToolDefinitionsFile(parsed)) {
        throw new Error(`${definitionsPath} does not match the expected StdioToolDefinitionsFile shape.`);
    }
    return parsed;
}
const DEFAULT_API_BASE_URL = 'https://api.bankstatemently.com';
/**
 * The ONE tool handler every registered tool shares (#6105 AC3) — dispatches
 * to `POST {apiBaseUrl}/v1/tools/{name}` with `X-API-Key` when a key is
 * configured, and returns the response body's `CallToolResult` verbatim.
 * With no key, `initialize`/`tools/list` need no network (this function is
 * never called for those methods) — a `tools/call` returns the SAME
 * auth-error result the hosted server emits (`authErrorResult`, sourced from
 * `buildToolAuthErrorResult()` at generation time — one literal, not two).
 * A REST 4xx/5xx surfaces as `isError: true` (#5049: tool failures are
 * results, never thrown).
 */
export async function callHostedTool(name, args, authErrorResult, apiBaseUrl = process.env.BANKSTATEMENTLY_API_URL ?? DEFAULT_API_BASE_URL, apiKey = process.env.BANKSTATEMENTLY_API_KEY) {
    if (!apiKey)
        return authErrorResult;
    let response;
    try {
        response = await fetch(`${apiBaseUrl}/v1/tools/${encodeURIComponent(name)}`, {
            method: 'POST',
            headers: { 'content-type': 'application/json', 'X-API-Key': apiKey },
            body: JSON.stringify(args ?? {}),
        });
    }
    catch (error) {
        return {
            content: [{ type: 'text', text: JSON.stringify({ error: `Request to Bankstatemently failed: ${error instanceof Error ? error.message : String(error)}` }) }],
            isError: true,
        };
    }
    const bodyText = await response.text();
    let body;
    try {
        body = JSON.parse(bodyText);
    }
    catch {
        body = bodyText;
    }
    if (!response.ok) {
        return {
            content: [{ type: 'text', text: JSON.stringify({ error: `Request failed with status ${response.status}`, body }) }],
            isError: true,
        };
    }
    // `POST /v1/tools/:name` returns the hosted handler's CallToolResult
    // verbatim (`routes/v1/tools.ts`) — but this package ships and versions
    // independently of the backend it talks to, so the response crosses a
    // REAL process/version boundary and is narrowed with `isCallToolResult`
    // rather than trusted blind.
    if (!isCallToolResult(body)) {
        return {
            content: [{ type: 'text', text: JSON.stringify({ error: 'Unexpected response shape from Bankstatemently', status: response.status }) }],
            isError: true,
        };
    }
    return body;
}
export function buildServer(definitions) {
    const server = new McpServer({ name: 'bankstatemently', version: definitions.version }, { capabilities: { tools: {} }, instructions: definitions.instructions });
    for (const def of definitions.tools) {
        server.registerTool(def.name, {
            title: def.title,
            description: def.description,
            inputSchema: fromJsonSchema(def.inputSchema),
            annotations: def.annotations,
        }, async (args) => callHostedTool(def.name, args, definitions.authErrorResult));
    }
    return server;
}
/** True when this file is the process entrypoint (`node dist/stdio.js`), not
 *  merely imported (by a test, or by another package). */
export function isMainModule() {
    const entrypoint = process.argv[1];
    return entrypoint !== undefined && path.resolve(entrypoint) === fileURLToPath(import.meta.url);
}
/* v8 ignore start -- CLI entrypoint guard: `isMainModule()` is only ever
 * true when this file is invoked directly (`node dist/stdio.js`), never
 * inside a vitest worker — nothing in this block runs under any test, by
 * construction. `readToolDefinitions`/`buildServer` (the real logic) ARE
 * covered directly, in `src/__tests__/stdioUnit.test.ts`. */
if (isMainModule()) {
    const definitions = readToolDefinitions();
    serveStdio(() => buildServer(definitions));
}
/* v8 ignore stop */
